import { describe, expect, it } from 'vitest';

/**
 * This scenario ships a caller workflow and a payload converter only because
 * the TypeScript SDK cannot send this operation yet. These tests fail when that
 * stops being true, so the scaffolding is deleted deliberately rather than
 * carried forever.
 *
 * The Python SDK already has the plumbing on main, and the caller API
 * (`workflow.signal_with_start_workflow`) on a branch, so this is a question of
 * when rather than whether.
 */
describe('the reason this scenario ships its own caller', () => {
  it('fails when the SDK gains a signal-with-start workflow API', async () => {
    const workflow = await import('@temporalio/workflow');

    const supported = Object.keys(workflow).filter((name) =>
      /signalWithStart/i.test(name),
    );

    expect(
      supported,
      [
        `@temporalio/workflow now exports ${supported.join(', ')}.`,
        'Use it instead: delete caller-workflow.ts and payload-converter.ts,',
        'and call the SDK from the scenario.',
      ].join('\n'),
    ).toEqual([]);
  });

  it('fails when the SDK can encode these messages as binary/protobuf', async () => {
    const { DefaultPayloadConverterWithProtobufs } =
      await import('@temporalio/common/lib/converter/protobuf-payload-converters');
    const protoPkg = await import('@temporalio/proto');

    const converter = new DefaultPayloadConverterWithProtobufs({
      protobufRoot: protoPkg as unknown as Record<string, unknown>,
    });

    const message =
      protoPkg.default.temporal.api.workflowservice.v1.SignalWithStartWorkflowExecutionRequest.create(
        { workflowId: 'canary' },
      );

    // The generated classes carry no reflection metadata, so the SDK's own
    // protobuf converters cannot serialize them. If this starts working, the
    // converter in this directory is redundant.
    let encoding: string | undefined;

    try {
      const payload = converter.toPayload(message);
      encoding = new TextDecoder().decode(payload?.metadata?.encoding);
    } catch {
      encoding = undefined;
    }

    expect(
      encoding,
      [
        `The SDK's protobuf converter now produces "${encoding}" for these messages.`,
        'If that is binary/protobuf with a messageType, delete payload-converter.ts',
        'and use the SDK converter.',
      ].join('\n'),
    ).not.toBe('binary/protobuf');
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

vi.mock('./handle-error', () => ({
  handleError: vi.fn(),
}));

vi.mock('./core-provider', () => ({
  runPreRequest: vi.fn(),
  runPostResponse: vi.fn(),
}));

import { runPostResponse, runPreRequest } from './core-provider';
import { handleError } from './handle-error';
import { requestFromAPI } from './request-from-api';

const mockRunPreRequest = vi.mocked(runPreRequest);
const mockRunPostResponse = vi.mocked(runPostResponse);

type MockResponseConfig = {
  body?: unknown;
  ok?: boolean;
  status?: number;
  statusText?: string;
};

const createMockFetch = (...responses: MockResponseConfig[]) => {
  let callIndex = 0;
  return vi.fn(async () => {
    const config = responses[Math.min(callIndex++, responses.length - 1)];
    return {
      json: () => Promise.resolve(config.body ?? {}),
      status: config.status ?? 200,
      statusText: config.statusText ?? 'OK',
      ok: config.ok ?? true,
    };
  }) as unknown as typeof fetch;
};

describe('requestFromAPI with hooks', () => {
  const endpoint = '/api/endpoint';

  beforeEach(() => {
    vi.clearAllMocks();
    mockRunPreRequest.mockImplementation(async (ctx) => ctx);
    mockRunPostResponse.mockImplementation(async (res) => res);
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  describe('preRequest hook', () => {
    it('should call runPreRequest before making the fetch', async () => {
      mockRunPreRequest.mockImplementation(async (ctx) => ({
        ...ctx,
        options: {
          ...ctx.options,
          headers: {
            ...(ctx.options.headers as Record<string, string>),
            Authorization: 'Bearer injected-token',
          },
        },
      }));

      const request = createMockFetch({
        status: 200,
        ok: true,
        body: { ok: true },
      });
      await requestFromAPI(endpoint, { request });

      expect(mockRunPreRequest).toHaveBeenCalledTimes(1);
      const fetchCallOptions = (request as ReturnType<typeof vi.fn>).mock
        .calls[0][1] as RequestInit;
      const headers = fetchCallOptions.headers as Record<string, string>;
      expect(headers['Authorization']).toBe('Bearer injected-token');
    });

    it('should not call runPreRequest when not in browser', async () => {
      const request = createMockFetch({ status: 200, ok: true, body: {} });
      await requestFromAPI(endpoint, { request, isBrowser: false });

      expect(mockRunPreRequest).not.toHaveBeenCalled();
    });

    it('should allow preRequest to modify the URL', async () => {
      mockRunPreRequest.mockImplementation(async (ctx) => ({
        ...ctx,
        url: ctx.url + '&injected=true',
      }));

      const request = createMockFetch({
        status: 200,
        ok: true,
        body: { ok: true },
      });
      await requestFromAPI(endpoint, { request });

      const fetchCallUrl = (request as ReturnType<typeof vi.fn>).mock
        .calls[0][0] as string;
      expect(fetchCallUrl).toContain('&injected=true');
    });
  });

  describe('postResponse hook', () => {
    it('should call runPostResponse after fetch', async () => {
      const request = createMockFetch({
        status: 200,
        ok: true,
        body: { data: 'test' },
      });
      await requestFromAPI(endpoint, { request });

      expect(mockRunPostResponse).toHaveBeenCalledTimes(1);
    });

    it('should pass retry callback that re-runs preRequest pipeline', async () => {
      let retryCallbackCaptured: (() => Promise<Response>) | undefined;

      mockRunPostResponse.mockImplementation(async (res, ctx) => {
        retryCallbackCaptured = ctx.retry;
        return res;
      });

      const request = createMockFetch({ status: 200, ok: true, body: {} });
      await requestFromAPI(endpoint, { request });

      expect(retryCallbackCaptured).toBeDefined();
      expect(mockRunPreRequest).toHaveBeenCalledTimes(1);

      await retryCallbackCaptured!();
      expect(mockRunPreRequest).toHaveBeenCalledTimes(2);
    });

    it('should use retried response when postResponse calls retry', async () => {
      const request = createMockFetch(
        { status: 401, ok: false, body: { message: 'unauthorized' } },
        { status: 200, ok: true, body: { data: 'refreshed' } },
      );

      mockRunPostResponse.mockImplementation(async (res, ctx) => {
        if (res.status === 401) {
          return ctx.retry();
        }
        return res;
      });

      const result = await requestFromAPI(endpoint, { request });

      expect(request).toHaveBeenCalledTimes(2);
      expect(result).toEqual({ data: 'refreshed' });
    });

    it('should not call runPostResponse when not in browser', async () => {
      const request = createMockFetch({
        status: 401,
        ok: false,
        body: { message: 'unauthorized' },
      });

      await requestFromAPI(endpoint, { request, isBrowser: false });

      expect(mockRunPostResponse).not.toHaveBeenCalled();
    });

    it('should pass correct context to postResponse including url and options', async () => {
      const request = createMockFetch({
        status: 200,
        ok: true,
        body: {},
      });

      mockRunPreRequest.mockImplementation(async (ctx) => ({
        ...ctx,
        options: {
          ...ctx.options,
          headers: {
            ...(ctx.options.headers as Record<string, string>),
            Authorization: 'Bearer test',
          },
        },
      }));

      await requestFromAPI(endpoint, { request });

      const postResponseCall = mockRunPostResponse.mock.calls[0];
      const context = postResponseCall[1];
      expect(context.url).toContain(endpoint);
      const headers = context.options.headers as Record<string, string>;
      expect(headers['Authorization']).toBe('Bearer test');
    });
  });

  describe('retry builds fresh headers', () => {
    it('should rebuild options from init.options on retry, not reuse stale headers', async () => {
      let callCount = 0;
      mockRunPreRequest.mockImplementation(async (ctx) => {
        callCount++;
        const headers = (ctx.options.headers as Record<string, string>) ?? {};
        headers['Authorization'] = `Bearer token-${callCount}`;
        return {
          ...ctx,
          options: { ...ctx.options, headers },
        };
      });

      mockRunPostResponse.mockImplementation(async (res, ctx) => {
        if (res.status === 401) {
          return ctx.retry();
        }
        return res;
      });

      const request = createMockFetch(
        { status: 401, ok: false, body: { message: 'unauthorized' } },
        { status: 200, ok: true, body: { data: 'ok' } },
      );

      await requestFromAPI(endpoint, { request });

      const firstCallHeaders = (
        (request as ReturnType<typeof vi.fn>).mock.calls[0][1] as RequestInit
      ).headers as Record<string, string>;
      const retryCallHeaders = (
        (request as ReturnType<typeof vi.fn>).mock.calls[1][1] as RequestInit
      ).headers as Record<string, string>;

      expect(firstCallHeaders['Authorization']).toBe('Bearer token-1');
      expect(retryCallHeaders['Authorization']).toBe('Bearer token-2');
    });
  });

  describe('no infinite retry loop', () => {
    it('should not call postResponse on the retried response', async () => {
      const request = createMockFetch(
        { status: 401, ok: false, body: { message: 'unauthorized' } },
        { status: 401, ok: false, body: { message: 'still unauthorized' } },
      );

      mockRunPostResponse.mockImplementation(async (res, ctx) => {
        if (res.status === 401) {
          return ctx.retry();
        }
        return res;
      });

      await requestFromAPI(endpoint, { request });

      expect(mockRunPostResponse).toHaveBeenCalledTimes(1);
      expect(request).toHaveBeenCalledTimes(2);
    });
  });

  describe('error in hooks', () => {
    it('should propagate preRequest errors to handleError', async () => {
      mockRunPreRequest.mockRejectedValue(new Error('preRequest exploded'));

      const request = createMockFetch({ status: 200, ok: true, body: {} });
      await requestFromAPI(endpoint, { request });

      expect(handleError).toHaveBeenCalled();
      expect(request).not.toHaveBeenCalled();
    });

    it('should propagate postResponse errors to handleError', async () => {
      mockRunPostResponse.mockRejectedValue(new Error('postResponse exploded'));

      const request = createMockFetch({ status: 200, ok: true, body: {} });
      await requestFromAPI(endpoint, { request });

      expect(handleError).toHaveBeenCalled();
    });

    it('should throw preRequest error when notifyOnError is false', async () => {
      mockRunPreRequest.mockRejectedValue(new Error('preRequest exploded'));

      const request = createMockFetch({ status: 200, ok: true, body: {} });
      const error = await requestFromAPI(endpoint, {
        request,
        notifyOnError: false,
      }).catch((e) => e);

      expect(error).toBeInstanceOf(Error);
      expect((error as Error).message).toBe('preRequest exploded');
    });
  });

  describe('long query bypass', () => {
    it('should still call postResponse on synthetic 414 response', async () => {
      const longQuery = 'x'.repeat(20000);
      const request = createMockFetch({ status: 200, ok: true, body: {} });

      await requestFromAPI(endpoint, {
        request,
        params: { query: longQuery },
      });

      expect(request).not.toHaveBeenCalled();
      expect(mockRunPostResponse).toHaveBeenCalledTimes(1);

      const postResponseCall = mockRunPostResponse.mock.calls[0];
      const response = postResponseCall[0];
      expect(response.status).toBe(414);
    });
  });

  describe('settings endpoint', () => {
    it('should still run preRequest for settings endpoint', async () => {
      const settingsEndpoint = '/api/v1/settings';
      const request = createMockFetch({
        status: 200,
        ok: true,
        body: { Auth: { Enabled: true } },
      });

      await requestFromAPI(settingsEndpoint, { request });

      expect(mockRunPreRequest).toHaveBeenCalledTimes(1);
    });
  });

  describe('error handling unchanged', () => {
    it('should call onError when response is not ok', async () => {
      const onError = vi.fn();
      const errorBody = { message: 'forbidden' };
      const request = createMockFetch({
        status: 403,
        ok: false,
        statusText: 'Forbidden',
        body: errorBody,
      });

      await requestFromAPI(endpoint, { request, onError });

      expect(onError).toHaveBeenCalledWith({
        body: errorBody,
        status: 403,
        statusText: 'Forbidden',
      });
    });

    it('should call handleError when no onError provided', async () => {
      const request = createMockFetch({
        status: 500,
        ok: false,
        statusText: 'Internal Server Error',
        body: { message: 'error' },
      });

      await requestFromAPI(endpoint, { request });

      expect(handleError).toHaveBeenCalled();
    });
  });
});

export enum Action {
  Pause,
  Unpause,
  Update,
  Reset,
}

import type { WorkflowEvent } from '$lib/types/events';
import { isWorkflowTaskFailedEventDueToReset } from '$lib/utilities/get-workflow-task-failed-event';
import {
  isActivityTaskScheduledEvent,
  isActivityTaskStartedEvent,
  isMarkerRecordedEvent,
  isNexusOperationCancelRequestedEvent,
  isNexusOperationScheduledEvent,
  isStartChildWorkflowExecutionInitiatedEvent,
  isTimerStartedEvent,
  isUpsertWorkflowSearchAttributesEvent,
  isWorkflowExecutionOptionsUpdatedEvent,
  isWorkflowExecutionSignaledEvent,
  isWorkflowExecutionStartedEvent,
  isWorkflowExecutionUpdateAcceptedEvent,
  isWorkflowExecutionUpdateRejectedEvent,
  isWorkflowTaskCompletedEvent,
} from '$lib/utilities/is-event-type';

export const getEventBillableActions = (
  event: WorkflowEvent,
  processedWorkflowTaskIds?: Set<string>,
): number => {
  try {
    if (isWorkflowExecutionStartedEvent(event)) {
      // Charge 2 additional for scheduled workflows if first run and not a retry
      const attempt = event.attributes?.attempt || 1;
      const firstRunId = event.attributes?.firstExecutionRunId;
      const currentRunId = event.attributes?.originalExecutionRunId;
      const isFirstRun = firstRunId === currentRunId;
      const isScheduledFirstRun =
        isFirstRun &&
        event.attributes?.searchAttributes?.indexedFields
          ?.TemporalScheduledById;
      if (attempt > 1) return 0;
      if (isScheduledFirstRun) return 3;
      return 1;
    }
    if (isActivityTaskScheduledEvent(event)) return 1;
    if (isTimerStartedEvent(event)) return 1;
    // Don't charge for signaled with start workflows
    if (isWorkflowExecutionSignaledEvent(event) && event.id !== '2') return 1;
    if (isNexusOperationScheduledEvent(event)) return 1;
    if (isNexusOperationCancelRequestedEvent(event)) return 1;
    if (isWorkflowExecutionUpdateAcceptedEvent(event)) return 1;
    if (isWorkflowExecutionUpdateRejectedEvent(event)) return 1;
    if (isWorkflowExecutionOptionsUpdatedEvent(event)) return 1;

    if (isUpsertWorkflowSearchAttributesEvent(event)) {
      const searchAttributeFields = Object.keys(
        event.attributes?.searchAttributes?.indexedFields ?? {},
      );
      if (
        searchAttributeFields?.length === 1 &&
        event.attributes?.searchAttributes?.indexedFields?.TemporalChangeVersion
      ) {
        // Non-billable search attribute update
        return 0;
      }
      return 1;
    }

    if (isMarkerRecordedEvent(event)) {
      const nonBillable = ['core_patch', 'Version'];
      if (nonBillable.includes(event?.attributes?.markerName ?? '')) return 0;

      // Check if any other markers are associated with same workflow task. If so, only charge for one marker, not all of them for the workflow task
      const workflowTaskId = event.attributes?.workflowTaskCompletedEventId;
      if (workflowTaskId && processedWorkflowTaskIds) {
        if (processedWorkflowTaskIds.has(String(workflowTaskId))) {
          return 0;
        }
        processedWorkflowTaskIds.add(String(workflowTaskId));
        return 1;
      }

      if (workflowTaskId) return 1;
    }

    if (isWorkflowTaskFailedEventDueToReset(event)) return 1;

    if (isStartChildWorkflowExecutionInitiatedEvent(event)) return 1;

    if (isActivityTaskStartedEvent(event)) {
      const attempts = event.attributes?.attempt || 1;
      return attempts - 1;
    }

    if (isWorkflowTaskCompletedEvent(event)) {
      return Math.min(
        event.attributes?.meteringMetadata
          ?.nonfirstLocalActivityExecutionAttempts || 0,
        100,
      );
    }

    return 0;
  } catch {
    return 0;
  }
};

import i18next from 'i18next';
import { vi } from 'vitest';

import { i18nNamespaces } from './src/lib/i18n';
import resources from './src/lib/i18n/locales';

i18next.init({
  fallbackLng: 'en',
  load: 'languageOnly',
  ns: i18nNamespaces,
  defaultNS: 'common',
  detection: {
    order: ['querystring', 'localStorage', 'navigator'],
    caches: ['localStorage'],
    lookupQuerystring: 'lng',
    lookupLocalStorage: 'locale',
  },
  resources,
});

const BroadcastChannelMock = vi.fn(() => ({
  addEventListener: () => {},
  postMessage: () => {},
}));

vi.stubGlobal('BroadcastChannel', BroadcastChannelMock);

const cryptoMock = {
  randomUUID: () => 'test-uuid-' + Math.random().toString(36).substring(2, 9),
};

vi.stubGlobal('crypto', cryptoMock);

vi.mock('esm-env', () => {
  const BROWSER = true;
  const DEV = false;
  return { BROWSER, DEV };
});

import { clearInRepoTemporaryRoot } from './scripts/catalog/test-temp-root';

export default async function setup(): Promise<void> {
  await clearInRepoTemporaryRoot();
}

import { chromium, FullConfig } from '@playwright/test';

import { connect, startWorkflows } from '../temporal/client';
import { createCodecServer } from '../temporal/codec-server';
import { runWorker } from '../temporal/worker';
import { startAuthStack } from '../utilities/auth-e2e-stack';
import { createTemporalServer } from '../utilities/temporal-server';
import { createUIServer } from '../utilities/ui-server';

const setupDependencies = async () => {
  const codecServer = await createCodecServer({ port: 8888 });
  const temporalServer = await createTemporalServer({
    headless: true,
    uiPort: 8080,
    codecEndpoint: 'http://127.0.0.1:8888',
  });
  const uiServer = await createUIServer('e2e');

  try {
    await uiServer.ready();
    await codecServer.start();
    await temporalServer.ready();

    const client = await connect();
    await runWorker();
    await startWorkflows(client, { waitForResult: false });

    // A second, auth-enabled ui-server plus a real identity provider, for
    // tests/e2e/auth-cookie-lifetimes.spec.ts. The rest of the suite is
    // unaffected: this listens on its own port and the other tests never
    // navigate to it.
    await startAuthStack();
  } catch (e) {
    console.log('Error setting up server: ', e);
  }
};

async function globalSetup(config: FullConfig) {
  const { mode } = config.metadata;
  const { baseURL } = config.projects[0].use;

  const browser = await chromium.launch();
  const page = await browser.newPage();

  if (mode === 'e2e') {
    await setupDependencies();
  }

  await page.goto(baseURL);

  await page
    .context()
    .storageState({ path: `./tests/${mode}/storageState.json` });
}

export default globalSetup;

import { expect, test } from '@playwright/test';

import { mockSettingsApi, mockWorkflowApis } from '~/test-utilities/mock-apis';
import { mockSchedulesApis } from '~/test-utilities/mock-apis';
import { mockWorkflow } from '~/test-utilities/mocks/workflow';

const workflowUrl = `/namespaces/default/workflows/${mockWorkflow.workflowExecutionInfo.execution.workflowId}/${mockWorkflow.workflowExecutionInfo.execution.runId}/history`;
const schedulesUrl = '/namespaces/default/schedules';

test.describe('Enable write actions by default', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto(workflowUrl);
    await mockWorkflowApis(page);
  });

  test('Cancel workflow button enabled', async ({ page }) => {
    test.slow();
    const cancelButton = page.getByRole('button', {
      name: 'Request Cancellation',
    });
    await expect(cancelButton).toBeVisible();
    await expect(cancelButton).toBeEnabled();
  });
});

test.describe('Disable write actions on workflow actions', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto(workflowUrl);
    await mockWorkflowApis(page);
    await mockSettingsApi(page, { DisableWriteActions: true });
  });

  test('Cancel workflow button disabled', async ({ page }) => {
    const cancelButton = page.getByRole('button', {
      name: 'Request Cancellation',
    });
    await expect(cancelButton).toBeDisabled();
  });
});

test.describe('Disable write actions on empty schedules list actions', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto(schedulesUrl);
    await mockSchedulesApis(page, true, true);
    await mockSettingsApi(page, { DisableWriteActions: true });
  });

  test('Create Schedule button is disabled', async ({ page }) => {
    await page.goto(schedulesUrl);

    const namespace = page.locator('h1');
    await expect(namespace).toHaveText('0 Schedules');
    const createButton = page.getByTestId('create-schedule');
    await expect(createButton).toBeDisabled();
  });
});

import { expect, type Request, test } from '@playwright/test';

import {
  mockSchedule,
  mockScheduleApi,
  mockSchedulesApis,
} from '~/test-utilities/mock-apis';

const scheduleUrl = '/namespaces/default/schedules/test-schedule';

const isPatchRequest = (request: Request) =>
  request.method() === 'POST' &&
  request.url().includes('/schedules/test-schedule/patch');

test.describe('Schedule actions', () => {
  test.beforeEach(async ({ page }) => {
    await mockSchedulesApis(page);
    await mockScheduleApi(page);
    await page.goto(scheduleUrl);
    await expect(page.getByTestId('schedule-name')).toContainText(
      'test-schedule',
    );
  });

  test("trigger pre-selects the schedule's overlap policy and sends it", async ({
    page,
  }) => {
    await page.getByLabel('Schedule Actions').click();
    await page.getByTestId('trigger-schedule').click();

    const modal = page.locator('#trigger-schedule-modal');
    await expect(modal).toBeVisible();
    await expect(modal.locator('#overlap-policy-Skip')).toBeChecked();

    const patchRequest = page.waitForRequest(isPatchRequest);
    await modal.getByTestId('confirm-modal-button').click();
    const body = (await patchRequest).postDataJSON();

    expect(body.patch.triggerImmediately.overlapPolicy).toBe('Skip');
  });

  test('trigger modal resets its overlap policy when reopened', async ({
    page,
  }) => {
    await page.getByLabel('Schedule Actions').click();
    await page.getByTestId('trigger-schedule').click();

    const modal = page.locator('#trigger-schedule-modal');
    await expect(modal).toBeVisible();
    await modal.locator('#overlap-policy-AllowAll').check();
    await expect(modal.locator('#overlap-policy-AllowAll')).toBeChecked();

    await modal.getByTestId('cancel-modal-button').click();
    await expect(modal).toBeHidden();

    await page.getByLabel('Schedule Actions').click();
    await page.getByTestId('trigger-schedule').click();
    await expect(modal).toBeVisible();
    await expect(modal.locator('#overlap-policy-Skip')).toBeChecked();
  });

  test('action modals stay usable after a successful backfill', async ({
    page,
  }) => {
    await page.getByLabel('Schedule Actions').click();
    await page.getByTestId('backfill-schedule').click();

    const backfillModal = page.locator('#backfill-schedule-modal');
    await expect(backfillModal).toBeVisible();

    const patchRequest = page.waitForRequest(isPatchRequest);
    await backfillModal.getByTestId('confirm-modal-button').click();
    const body = (await patchRequest).postDataJSON();

    expect(body.patch.backfillRequest).toHaveLength(1);
    expect(body.patch.backfillRequest[0].startTime).toBeTruthy();
    expect(body.patch.backfillRequest[0].endTime).toBeTruthy();

    await expect(backfillModal).toBeHidden();

    await page.getByLabel('Schedule Actions').click();
    await page.getByTestId('trigger-schedule').click();

    const triggerModal = page.locator('#trigger-schedule-modal');
    await expect(triggerModal).toBeVisible();
    await expect(
      triggerModal.getByTestId('confirm-modal-button'),
    ).toBeEnabled();
  });

  test('backfill modal shows times based on the schedule timezone', async ({
    page,
  }) => {
    await mockScheduleApi(page, {
      ...mockSchedule,
      schedule: {
        ...mockSchedule.schedule,
        spec: { ...mockSchedule.schedule.spec, timezoneName: 'Asia/Tokyo' },
      },
    });
    await page.goto(scheduleUrl);
    await expect(page.getByTestId('schedule-name')).toContainText(
      'test-schedule',
    );

    await page.getByLabel('Schedule Actions').click();
    await page.getByTestId('backfill-schedule').click();

    const modal = page.locator('#backfill-schedule-modal');
    await expect(modal).toBeVisible();
    await expect(modal.getByText('Based on Asia/Tokyo')).toBeVisible();
  });

  test('backfill rejects an end time before the start time', async ({
    page,
  }) => {
    await page.getByLabel('Schedule Actions').click();
    await page.getByTestId('backfill-schedule').click();

    const modal = page.locator('#backfill-schedule-modal');
    await expect(modal).toBeVisible();
    await expect(
      modal.getByText('Based on Universal Standard Time (UTC)'),
    ).toBeVisible();

    const popup = modal.locator('.z-30');
    await modal.locator('#backfill-start-date').click();
    await popup.getByRole('button', { name: 'Next Month' }).click();
    await popup.getByRole('button', { name: '15', exact: true }).click();

