  await page.context().addCookies([
    {
      name: 'user0',
      value: makeUserCookie('test-access-token-123'),
      domain: 'localhost',
      path: '/',
    },
  ]);

  await page.goto(baseURL);
  await page.getByTestId('user-menu-trigger').click();
  await page.getByRole('menuitem', { name: /log out/i }).click();

